  bool discoveryRunning() =>
      RustLib.instance.api.crateApiNudgeNudgeAppDiscoveryRunning(that: this);

  String downloadDir() =>
      RustLib.instance.api.crateApiNudgeNudgeAppDownloadDir(that: this);

