      .crateApiNudgeNudgeAppWarm(that: this, deviceId: deviceId);

  /// The link, while sharing with browsers.
  String? webShareUrl() =>
      RustLib.instance.api.crateApiNudgeNudgeAppWebShareUrl(that: this);
